/**
 * INDIA NODE 1 — PARSE_Input
 * Mode: Run Once for All Items
 *
 * Normalises the webhook body into the fields the rest of the chain reads by
 * name.
 *
 * SCOPE NOTE — this node is deliberately NOT hardened yet. It still throws on a
 * missing image_url, which aborts the run before Respond_to_Webhook1 and leaves
 * the caller with an empty body, and it performs no SSRF checks on a URL that a
 * third party (OpenRouter) will dereference. Those are roadmap items 7.4 and 7.5
 * and they need a validation-routing node plus a RESPOND_BadRequest node, which
 * is a change to the workflow's shape rather than to this file. The US
 * implementation to port from is scripts/nodes/01_validate_input.js.
 *
 * It lives in a file rather than inside the patch script so the JavaScript is
 * reviewable as JavaScript — the same reason the US nodes do.
 */

const body = $input.first().json.body || {};

const image_url = body.image_url || null;
const site_id = body.site_id || 'unknown';

if (!image_url || image_url.trim().length === 0) {
  throw new Error('Missing required field: image_url not found in request body.');
}

// asset_tag identifies WHICH device at the site. A site holds many devices and is
// audited repeatedly, so without it two audits of one address are
// indistinguishable. inspector_id records who captured the evidence; it is what
// prints as "Captured by" on the report, and it is deliberately NOT the sign-off
// name — that requires a qualified reviewer, not whoever ran the scan.
function clean(value, fallback, maxLength) {
  const out = String(value === undefined || value === null ? '' : value).trim();
  return (out || fallback).slice(0, maxLength || 64);
}

return [{
  json: {
    image_url: image_url.trim(),
    site_id: site_id,
    asset_tag: clean(body.asset_tag, '', 64) || null,
    inspector_id: clean(body.inspector_id, 'UNASSIGNED', 64)
  }
}];

/**
 * INDIA NODE 3 — PARSE_Response
 * Mode: Run Once for All Items
 *
 * Parses the model output and DERIVES the verdict. The node keeps its original
 * name so nothing downstream breaks, but its job has changed: it no longer
 * transcribes what the model said, it decides.
 *
 * ---------------------------------------------------------------------------
 * WHY THE STATUS IS COMPUTED HERE AND NOT READ FROM THE MODEL
 * ---------------------------------------------------------------------------
 * Previously this node did `{...parsed}` and the model's own `status` string went
 * straight into the database and into IF_NonCompliant. Two failures followed from
 * that:
 *
 *   1. A model revision emitting "PASS", "OK" or "PARTIAL" instead of
 *      "COMPLIANT" would not match "NON-COMPLIANT" in the IF node, so every
 *      audit — including one showing a discharged extinguisher — would have taken
 *      the compliant branch and raised no alert. Silently.
 *   2. The verdict that triggers escalation was unreviewable. Nobody could say
 *      why a given photograph was judged compliant, because the reason lived in
 *      the model's head.
 *
 * Now the model reports observations and severities; the status is arithmetic on
 * those. It is inspectable, stable across model versions, and testable offline —
 * which is what scripts/test_india.mjs does.
 *
 * PRECEDENCE IS DELIBERATE, and copied from the US workflow:
 *   critical  ->  weak evidence  ->  ordinary deficiency  ->  clean
 * A confidence gate must never be able to suppress a life-safety finding. The
 * cost asymmetry between a false alarm and a missed blocked exit is not close.
 */

const source = $('PARSE_Input').first().json;
const payloadMeta = $('BUILD_Vision_Payload').first().json;
const audit_timestamp = new Date().toISOString();

/** Shared shape so every exit from this node returns the same fields. */
function base(extra) {
  const out = {
    site_id: payloadMeta.site_id || source.site_id || 'unknown',
    asset_tag: source.asset_tag || null,
    inspector_id: source.inspector_id || 'UNASSIGNED',
    image_url: source.image_url || null,
    audit_timestamp: audit_timestamp
  };
  for (const k in extra) out[k] = extra[k];
  return out;
}

// ------------------------------------------------------------------ parsing
const raw = $input.first().json.choices?.[0]?.message?.content || '';

const cleaned = String(raw)
  .replace(/```json\s*/gi, '')
  .replace(/```\s*/g, '')
  .trim();

let parsed = null;
let parseError = null;
try {
  parsed = JSON.parse(cleaned);
} catch (e) {
  parseError = e.message;
}

// Arrays are excluded explicitly. `typeof [] === 'object'` and `[]` is truthy, so
// a bare `[]` or `[{...}]` from the model would otherwise pass this gate, produce
// no deficiencies, and be recorded as a COMPLIANT audit — a false pass arriving
// through a type check that looked correct.
if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) {
  // ERROR is a real status, not a silent pass. alert_required is true so ops
  // hears about a broken automated pass rather than it looking like a clean bill.
  return [{
    json: base({
      status: 'ERROR',
      alert_required: true,
      critical: false,
      confidence: 'LOW',
      image_quality: 'UNKNOWN',
      equipment_type: 'Unknown',
      observations: 'Failed to parse the model response: ' + (parseError || 'empty response'),
      deficiencies: [],
      violations: ['AI_PARSE_ERROR'],
      unverifiable_items: ['Entire checklist — the automated pass did not produce a usable result.'],
      reinspect_required: true,
      reinspect_reasons: ['Automated analysis failed; resubmit the photograph or inspect manually.'],
      risk_score: 0,
      critical_count: 0,
      major_count: 0,
      minor_count: 0,
      deficiency_count: 0,
      raw_model_excerpt: cleaned.slice(0, 600)
    })
  }];
}

// ------------------------------------------------------------ normalisation
function enumOf(value, allowed, fallback) {
  const v = String(value === undefined || value === null ? '' : value).trim().toUpperCase();
  return allowed.indexOf(v) !== -1 ? v : fallback;
}

function toArray(value) {
  if (Array.isArray(value)) return value;
  if (value === undefined || value === null || value === '') return [];
  return [value];
}

function text(value, max) {
  if (value === undefined || value === null) return null;
  const s = String(value).trim();
  return s ? s.slice(0, max || 600) : null;
}

const confidence = enumOf(parsed.confidence, ['HIGH', 'MEDIUM', 'LOW'], 'MEDIUM');
const image_quality = enumOf(parsed.image_quality, ['GOOD', 'FAIR', 'POOR'], 'FAIR');
const equipment_type = text(parsed.equipment_type, 120) || 'Unknown';
const observations = text(parsed.observations, 4000) || 'No observations returned.';

const KNOWN_CODES = Array.isArray(payloadMeta.checklist_codes) ? payloadMeta.checklist_codes : [];
const CODE_SEVERITY = payloadMeta.checklist_severity || {};

const SEVERITY_RANK = { CRITICAL: 0, MAJOR: 1, MINOR: 2 };

/**
 * Severity bias is UPWARD, in both directions it could go wrong.
 *
 * Two inputs disagree about how bad a finding is: the checklist severity we
 * authored for that code, and whatever the model put in the deficiency. The rule
 * is to take the MORE SEVERE of the two, never to let one override the other.
 *
 *   - The checklist is a floor. The model does not get to downgrade a defect the
 *     code basis treats as critical, so a blocked extinguisher reported as MINOR
 *     is still CRITICAL.
 *   - The model can still escalate. If it tags ISI_MARK_MISSING — a marking
 *     defect, MINOR by policy — as CRITICAL, it is probably describing something
 *     worse than the code it reached for. Letting the checklist win outright there
 *     would suppress a real escalation, which is the expensive direction of the
 *     error.
 *
 * An unrecognised severity string normalises to MAJOR, never MINOR: if the model
 * invents a value we do not understand, the safe assumption is that the finding
 * matters.
 */
function severityOf(deficiency) {
  const reported = enumOf(deficiency && deficiency.severity, ['CRITICAL', 'MAJOR', 'MINOR'], 'MAJOR');
  const declared = CODE_SEVERITY[String(deficiency && deficiency.code).trim()];
  if (!declared) return reported;
  return SEVERITY_RANK[declared] <= SEVERITY_RANK[reported] ? declared : reported;
}

const deficiencies = toArray(parsed.deficiencies)
  .filter(function (d) { return d && typeof d === 'object'; })
  .map(function (d) {
    const code = text(d.code, 64);
    return {
      // Flagged rather than dropped: a finding whose code we do not recognise is
      // still a finding, and discarding it would lose a real defect.
      code: code || 'UNSPECIFIED',
      code_known: code ? KNOWN_CODES.indexOf(code) !== -1 : false,
      severity: severityOf(d),
      finding: text(d.finding, 600) || 'Unspecified finding.',
      observed: text(d.observed, 600),
      requirement: text(d.requirement, 600),
      code_reference: text(d.code_reference, 240),
      remediation: text(d.remediation, 600)
    };
  });

const unverifiable_items = toArray(parsed.unverifiable_items)
  .map(function (u) { return text(u, 400); })
  .filter(Boolean);

// -------------------------------------------------------------- arithmetic
function countAt(severity) {
  return deficiencies.filter(function (d) { return d.severity === severity; }).length;
}

const critical_count = countAt('CRITICAL');
const major_count = countAt('MAJOR');
const minor_count = countAt('MINOR');
const deficiency_count = deficiencies.length;

const SEVERITY_WEIGHT = { CRITICAL: 100, MAJOR: 25, MINOR: 5 };
const risk_score = Math.min(
  100,
  critical_count * SEVERITY_WEIGHT.CRITICAL +
  major_count * SEVERITY_WEIGHT.MAJOR +
  minor_count * SEVERITY_WEIGHT.MINOR
);

const has_critical = critical_count > 0;
const evidence_is_weak = confidence === 'LOW' || image_quality === 'POOR';
const needs_reinspect = parsed.reinspect_required === true || evidence_is_weak;

const reinspect_reasons = [];
if (parsed.reinspect_required === true) {
  reinspect_reasons.push('The automated pass flagged this photograph as inadequate to judge.');
}
if (confidence === 'LOW') {
  reinspect_reasons.push('Model confidence is LOW.');
}
if (image_quality === 'POOR') {
  reinspect_reasons.push('Image quality is POOR — retake with better framing and lighting.');
}

// ----------------------------------------------------- deterministic status
let status;
if (has_critical) {
  // Fail-safe: a critical finding escalates even at LOW confidence or POOR
  // image quality. A confidence gate must not be able to hide one.
  status = 'NON-COMPLIANT';
} else if (needs_reinspect) {
  status = 'REINSPECT';
} else if (major_count > 0) {
  status = 'NON-COMPLIANT';
} else if (minor_count > 0) {
  // Real inspection practice distinguishes "deficiencies noted" from "failed".
  // Collapsing them trains operators to ignore alerts.
  status = 'CONDITIONAL';
} else {
  status = 'COMPLIANT';
}

/**
 * IF_NonCompliant switches on this boolean rather than comparing status strings.
 * Keeping the branch condition in code means adding a status can never silently
 * create an unrouted path — which is precisely how REINSPECT ended up handled in
 * the notifier but never reachable.
 */
const alert_required = status !== 'COMPLIANT';

// Flat strings, kept for the `violations` text column and for the dashboard's
// India fallback rendering. Severity is prefixed so the flat list is still
// ordered information rather than an undifferentiated blob.
const violations = deficiencies.map(function (d) {
  return '[' + d.severity + '] ' + d.finding;
});

return [{
  json: base({
    status: status,
    alert_required: alert_required,
    critical: has_critical,
    confidence: confidence,
    image_quality: image_quality,
    equipment_type: equipment_type,
    observations: observations,
    deficiencies: deficiencies,
    violations: violations,
    unverifiable_items: unverifiable_items,
    reinspect_required: needs_reinspect,
    reinspect_reasons: reinspect_reasons,
    risk_score: risk_score,
    critical_count: critical_count,
    major_count: major_count,
    minor_count: minor_count,
    deficiency_count: deficiency_count,
    // Surfaced so a reviewer can see the model returned a code outside the
    // checklist it was given, rather than that being invisible.
    unknown_codes: deficiencies.filter(function (d) { return !d.code_known; })
      .map(function (d) { return d.code; })
  })
}];

/**
 * INDIA NODE 5 — NOTIFY_OpsManager
 * Mode: Run Once for All Items
 *
 * Composes the Slack, Telegram and email bodies. Reads SHAPE_Response's output.
 *
 * Output field names are unchanged (telegram_message, slack_message, email_html,
 * email_subject, alert, …) so SEND_Slack, SEND_Telegram and the Gmail node need
 * no edits.
 *
 * ---------------------------------------------------------------------------
 * THREE FIXES BEYOND THE SEVERITY REWRITE
 * ---------------------------------------------------------------------------
 * 1. `$input.item` -> `$input.first()`.
 *    The previous version read `$input.item.json`, which n8n only provides in
 *    "Run Once for Each Item" mode. This node has no `mode` parameter set, so it
 *    runs in the default all-items mode, where `.item` is not available. Using
 *    `.first()` is valid in either mode, so the question stops mattering.
 *
 * 2. Telegram and Slack payloads are escaped.
 *    SEND_Telegram posts with parse_mode: HTML. Findings are model prose, so a
 *    single "&" or "<" in an observation makes Telegram reject the whole message
 *    with a parse error — the alert is lost, and lost precisely on the messiest
 *    findings, which are the ones most likely to contain odd characters. Slack
 *    needs the same three characters escaped.
 *
 * 3. The footer said "FireScan Mumbai | Powered by Arvami Solutionz".
 *    Stale product name, stale company. It is now KRATU AI Labs / AQUILA, with
 *    the statute stated the way lib/regions.ts states it.
 */

const a = $input.first().json;

const status = a.status || 'UNKNOWN';
const site_id = a.site_id || 'unknown';
const asset_tag = a.asset_tag || null;
const equipment = a.equipment_type || 'Unknown Equipment';
const confidence = a.confidence || 'N/A';
const image_quality = a.image_quality || 'N/A';
const risk_score = typeof a.risk_score === 'number' ? a.risk_score : null;
const persisted = a.persisted !== false;
const timestamp = a.audit_timestamp || new Date().toISOString();

const counts = a.severity_counts || {};
const critical_count = counts.critical || 0;
const major_count = counts.major || 0;
const minor_count = counts.minor || 0;

const indiaTime = new Date(timestamp).toLocaleString('en-IN', {
  timeZone: 'Asia/Kolkata',
  dateStyle: 'medium',
  timeStyle: 'short'
});

// ---------------------------------------------------------------- coercion
/**
 * Tolerates an array, a stringified JSON array, or a bare string. The India
 * table stores `violations` as stringified JSON in a text column, and this node
 * may be re-run against a row read back from it.
 */
function toArray(value) {
  if (Array.isArray(value)) return value;
  if (value === null || value === undefined || value === '') return [];
  if (typeof value === 'string') {
    const trimmed = value.trim();
    if (!trimmed) return [];
    try {
      const parsed = JSON.parse(trimmed);
      return Array.isArray(parsed) ? parsed : [trimmed];
    } catch (e) {
      // Keep the whole string as one finding. Dropping a violation line because
      // it would not parse is not an acceptable failure for a safety alert.
      return [trimmed];
    }
  }
  return [String(value)];
}

/**
 * Escapes the three characters that break Telegram's HTML parse mode and Slack's
 * mrkdwn. Applied to every interpolated value rather than to the finished string,
 * so the formatting characters we author ourselves survive.
 */
function esc(value) {
  return String(value === undefined || value === null ? '' : value)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

const deficiencies = toArray(a.deficiencies).filter(function (d) {
  return d && typeof d === 'object';
});
const violations = toArray(a.violations);
const unverifiable = toArray(a.unverifiable_items);
const reinspect_reasons = toArray(a.reinspect_reasons);
const unknown_codes = toArray(a.unknown_codes);

// -------------------------------------------------------------- framing
let title;
let emoji;
let actionText;

if (status === 'ERROR') {
  title = 'AUDIT SYSTEM ERROR — NOT INSPECTED';
  emoji = '\u26a0\ufe0f';
  actionText = 'The automated pass failed. This site has NOT been assessed — resubmit the photograph or inspect manually.';
} else if (critical_count > 0) {
  title = 'CRITICAL FINDING — IMMEDIATE ACTION REQUIRED';
  emoji = '\ud83d\udd34';
  actionText = 'Attend the site now. A critical finding means the equipment cannot be relied on, or cannot be reached.';
} else if (status === 'NON-COMPLIANT') {
  title = 'AUDIT FAILED — REMEDIATION REQUIRED';
  emoji = '\ud83d\udfe0';
  actionText = 'Notify the site supervisor and raise a maintenance job against the asset.';
} else if (status === 'REINSPECT') {
  title = 'REINSPECT REQUIRED — EVIDENCE INADEQUATE';
  emoji = '\ud83d\udcf8';
  actionText = 'The photograph cannot settle the checklist. Retake it with better framing and lighting; do not record this as a pass.';
} else if (status === 'CONDITIONAL') {
  title = 'DEFICIENCIES NOTED — NOT A FAILURE';
  emoji = '\ud83d\udfe1';
  actionText = 'Minor items only. Schedule with routine maintenance; no immediate attendance needed.';
} else {
  // COMPLIANT should not reach here — IF_NonCompliant branches on
  // alert_required, which is false for it. Handled anyway so a future status
  // cannot produce a headline reading "undefined".
  title = 'AUDIT STATUS: ' + status;
  emoji = '\u26aa';
  actionText = 'Review required.';
}

/**
 * The severity line is the point of this rewrite. "NON-COMPLIANT" plus five
 * undifferentiated strings told an ops manager nothing about whether to get in a
 * van. Counts by tier, with the risk score, do.
 */
const severityLine = [
  critical_count ? critical_count + ' CRITICAL' : null,
  major_count ? major_count + ' MAJOR' : null,
  minor_count ? minor_count + ' MINOR' : null
].filter(Boolean).join(' \u00b7 ') || 'no deficiencies recorded';

// ----------------------------------------------------------- finding lists
/** Plain-text finding block, severity first so it is scannable. */
function plainFindings() {
  if (deficiencies.length === 0) {
    return violations.length
      ? violations.map(function (v, i) { return (i + 1) + '. ' + esc(v); }).join('\n')
      : 'None recorded';
  }
  return deficiencies.map(function (d, i) {
    const lines = [
      (i + 1) + '. [' + esc(d.severity || 'MAJOR') + '] ' + esc(d.finding || 'Unspecified finding.')
    ];
    if (d.code_reference) lines.push('     Code: ' + esc(d.code_reference));
    if (d.remediation) lines.push('     Fix:  ' + esc(d.remediation));
    return lines.join('\n');
  }).join('\n');
}

function slackFindings() {
  if (deficiencies.length === 0) {
    return violations.length
      ? violations.map(function (v) { return '\u2022 ' + esc(v); }).join('\n')
      : '\u2022 None recorded';
  }
  return deficiencies.map(function (d) {
    const head = '\u2022 `' + esc(d.severity || 'MAJOR') + '` ' + esc(d.finding || 'Unspecified finding.');
    const ref = d.code_reference ? '\n    _' + esc(d.code_reference) + '_' : '';
    const fix = d.remediation ? '\n    Fix: ' + esc(d.remediation) : '';
    return head + ref + fix;
  }).join('\n');
}

function htmlFindings() {
  if (deficiencies.length === 0) {
    const items = violations.length ? violations : ['None recorded'];
    return items.map(function (v) {
      return '<li style="padding:4px 0;">' + esc(v) + '</li>';
    }).join('');
  }
  const SEV_COLOR = { CRITICAL: '#b3261e', MAJOR: '#b26a00', MINOR: '#5f6368' };
  return deficiencies.map(function (d) {
    const sev = String(d.severity || 'MAJOR').toUpperCase();
    const color = SEV_COLOR[sev] || '#5f6368';
    return '<li style="padding:6px 0;">'
      + '<span style="display:inline-block;min-width:64px;font-size:11px;font-weight:700;'
      + 'letter-spacing:.06em;color:' + color + ';">' + esc(sev) + '</span> '
      + esc(d.finding || 'Unspecified finding.')
      + (d.code_reference ? '<div style="font-size:12px;color:#6b7280;padding-left:64px;">' + esc(d.code_reference) + '</div>' : '')
      + (d.remediation ? '<div style="font-size:12px;color:#374151;padding-left:64px;">Fix: ' + esc(d.remediation) + '</div>' : '')
      + '</li>';
  }).join('');
}

// ------------------------------------------------------------- caveat block
/**
 * Caveats are appended to every channel. The un-persisted warning matters most:
 * when the database write failed, this message IS the record, and the reader has
 * to be told that rather than discovering it later.
 */
const caveats = [];
if (!persisted) {
  caveats.push('NOT WRITTEN TO THE AUDIT DATABASE. This alert is the only copy of this finding \u2014 retain it.');
}
if (unverifiable.length) {
  caveats.push('Could not be verified from the photograph: ' + unverifiable.map(esc).join('; '));
}
if (reinspect_reasons.length && status !== 'REINSPECT') {
  caveats.push('Reinspection flagged: ' + reinspect_reasons.map(esc).join('; '));
}
if (unknown_codes.length) {
  caveats.push('Model returned checklist codes we do not recognise (' + unknown_codes.map(esc).join(', ')
    + '). The prompt and the parser may have drifted.');
}

const RULE = '\u2501'.repeat(30);
const FOOTER = 'KRATU AI Labs \u00b7 AQUILA IND \u00b7 NBC 2016 Part 4, enforceable under MFPLSM Act 2006 / Rules 2009 \u00b7 AHJ: CFO, MCGM';
const ADVISORY = 'Advisory screening from a photograph. Not a Form B certificate and not a substitute for inspection by a Licensed Agency.';

// ------------------------------------------------------------ plain (Telegram)
const plainAlert = [
  emoji + ' ' + title,
  RULE,
  'Site        : ' + esc(site_id),
  asset_tag ? 'Asset       : ' + esc(asset_tag) : null,
  'Equipment   : ' + esc(equipment),
  'Status      : ' + esc(status),
  'Severity    : ' + severityLine,
  risk_score !== null ? 'Risk score  : ' + risk_score + '/100' : null,
  'Confidence  : ' + esc(confidence) + '   Image: ' + esc(image_quality),
  'Time (IST)  : ' + esc(indiaTime),
  '',
  status === 'REINSPECT' ? 'WHY REINSPECTION IS NEEDED:' : 'FINDINGS:',
  status === 'REINSPECT' && reinspect_reasons.length
    ? reinspect_reasons.map(function (r, i) { return (i + 1) + '. ' + esc(r); }).join('\n')
    : plainFindings(),
  caveats.length ? '' : null,
  caveats.length ? caveats.map(function (c) { return '! ' + c; }).join('\n') : null,
  RULE,
  'Action: ' + actionText,
  ADVISORY
].filter(function (line) { return line !== null; }).join('\n');

// ------------------------------------------------------------------- Slack
const slackAlert = [
  ':fire: *' + esc(title) + '*',
  RULE,
  '*Site:* `' + esc(site_id) + '`' + (asset_tag ? '   *Asset:* `' + esc(asset_tag) + '`' : ''),
  '*Equipment:* ' + esc(equipment),
  '*Status:* `' + esc(status) + '`   *Severity:* ' + severityLine
    + (risk_score !== null ? '   *Risk:* ' + risk_score + '/100' : ''),
  '*Confidence:* ' + esc(confidence) + '   *Image:* ' + esc(image_quality),
  '*Time (IST):* ' + esc(indiaTime),
  '',
  '*' + (status === 'REINSPECT' ? 'WHY REINSPECTION IS NEEDED:' : 'FINDINGS:') + '*',
  status === 'REINSPECT' && reinspect_reasons.length
    ? reinspect_reasons.map(function (r) { return '\u2022 ' + esc(r); }).join('\n')
    : slackFindings(),
  caveats.length ? '' : null,
  caveats.length ? caveats.map(function (c) { return ':warning: ' + c; }).join('\n') : null,
  RULE,
  '*Action:* ' + actionText,
  '_' + ADVISORY + '_'
].filter(function (line) { return line !== null; }).join('\n');

// ------------------------------------------------------------------- email
const bandColor = status === 'ERROR' ? '#5f6368'
  : critical_count > 0 ? '#b3261e'
  : status === 'NON-COMPLIANT' ? '#c2410c'
  : '#b26a00';

function row(label, value, last) {
  const border = last ? '' : 'border-bottom:1px solid #e5e7eb;';
  return '<tr>'
    + '<td style="padding:8px;' + border + 'font-weight:bold;width:38%;">' + esc(label) + '</td>'
    + '<td style="padding:8px;' + border + '">' + value + '</td>'
    + '</tr>';
}

const htmlAlert = [
  '<div style="font-family:Arial,Helvetica,sans-serif;max-width:640px;margin:0 auto;border:1px solid #ddd;border-radius:8px;overflow:hidden;">',
  '<div style="background:' + bandColor + ';color:#fff;padding:18px 20px;">',
  '<div style="font-size:11px;letter-spacing:.14em;opacity:.85;">KRATU AI LABS \u00b7 AQUILA IND</div>',
  '<h2 style="margin:6px 0 0;font-size:19px;">' + esc(title) + '</h2>',
  '</div>',
  '<div style="padding:16px 20px;background:#f9fafb;">',
  '<table style="width:100%;border-collapse:collapse;font-size:14px;">',
  row('Site', '<code>' + esc(site_id) + '</code>'),
  asset_tag ? row('Asset tag', '<code>' + esc(asset_tag) + '</code>') : '',
  row('Equipment', esc(equipment)),
  row('Status', '<strong style="color:' + bandColor + ';">' + esc(status) + '</strong>'),
  row('Severity', severityLine + (risk_score !== null ? ' &nbsp;(risk ' + risk_score + '/100)' : '')),
  row('Confidence', esc(confidence) + ' &nbsp;\u00b7&nbsp; image quality ' + esc(image_quality)),
  row('Time (IST)', esc(indiaTime), true),
  '</table>',
  '</div>',
  '<div style="padding:16px 20px;">',
  '<h3 style="color:#374151;margin:0 0 8px;font-size:14px;letter-spacing:.06em;">',
  status === 'REINSPECT' ? 'WHY REINSPECTION IS NEEDED' : 'FINDINGS',
  '</h3>',
  '<ul style="color:#4b5563;margin:0;padding-left:20px;font-size:14px;">',
  status === 'REINSPECT' && reinspect_reasons.length
    ? reinspect_reasons.map(function (r) { return '<li style="padding:4px 0;">' + esc(r) + '</li>'; }).join('')
    : htmlFindings(),
  '</ul>',
  '</div>',
  caveats.length
    ? '<div style="padding:12px 20px;background:#fef3c7;border-top:1px solid #fde68a;font-size:13px;color:#78350f;">'
        + caveats.map(function (c) { return '<div style="padding:2px 0;">\u26a0\ufe0f ' + c + '</div>'; }).join('')
        + '</div>'
    : '',
  '<div style="background:#eff6ff;padding:14px 20px;border-top:1px solid #ddd;font-size:14px;">',
  '<strong>Required action:</strong> ' + esc(actionText),
  '</div>',
  '<div style="background:#f3f4f6;padding:12px 20px;font-size:11px;color:#6b7280;line-height:1.5;">',
  esc(ADVISORY) + '<br>' + esc(FOOTER) + '<br>' + esc(indiaTime),
  '</div>',
  '</div>'
].join('');

// Subject leads with the severity, because that is what determines whether the
// mail gets opened now or after lunch.
const subjectLead = critical_count > 0 ? 'CRITICAL' : status;

return [{
  json: {
    telegram_message: plainAlert + '\n' + esc(FOOTER),
    slack_message: slackAlert,
    email_html: htmlAlert,
    email_subject: emoji + ' AQUILA IND \u2014 ' + subjectLead + ': ' + site_id
      + (asset_tag ? ' / ' + asset_tag : ''),

    // Field names below are unchanged so the notifier nodes need no edits.
    alert: plainAlert,
    site_id: site_id,
    status: status,
    equipment_type: equipment,
    violations: violations,
    reinspect_reasons: reinspect_reasons,
    audit_timestamp: timestamp,

    // Carried through so a downstream node (a work-order webhook, say) does not
    // have to reach back into SHAPE_Response.
    asset_tag: asset_tag,
    critical: critical_count > 0,
    risk_score: risk_score,
    severity_counts: { critical: critical_count, major: major_count, minor: minor_count },
    deficiencies: deficiencies,
    persisted: persisted
  }
}];

// Get the binary data object
const binaryData = $input.first().binary;

// Use the internal n8n helper to force-read the file from disk into memory
const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');

if (!buffer) {
  throw new Error('Failed to extract image data from disk.');
}

// Convert the buffer to a base64 string
const base64String = buffer.toString('base64');
const mediaType = binaryData.mimeType || 'image/jpeg';

return [{
  json: {
    image_base64: base64String,
    media_type: mediaType,
    site_id: $input.first().json.site_id
  }
}];

/**
 * INDIA NODE 4 — SHAPE_Response   (NEW NODE)
 * Mode: Run Once for All Items
 * Position in chain: LOG_Audit -> SHAPE_Response -> IF_NonCompliant
 *
 * Two jobs, both of which used to have no home in this workflow.
 *
 * ---------------------------------------------------------------------------
 * 1. A DATABASE OUTAGE MUST NOT SWALLOW A FINDING  (roadmap 7.3)
 * ---------------------------------------------------------------------------
 * LOG_Audit previously had no onError, so a Postgres hiccup aborted the whole
 * execution: no Slack message, no Telegram message, and an empty HTTP body. A
 * blocked fire exit would have gone unreported because a database was briefly
 * unavailable — the finding was already computed and sitting in memory, and it
 * was thrown away.
 *
 * LOG_Audit now runs with onError: continueRegularOutput, which means its output
 * on failure is an error object rather than the inserted row. This node inspects
 * that, sets `persisted`, and lets the audit continue. The alert still fires, the
 * caller still gets the verdict, and both are told the record was not written.
 *
 * `persisted` is a degraded state, never a silent one. The dashboard already
 * renders it (it was built for the US workflow) and BUILD_Alert says so in the
 * message body, because an alert that is the ONLY copy of a finding needs to be
 * kept rather than glanced at.
 *
 * ---------------------------------------------------------------------------
 * 2. AN EXPLICIT RESPONSE CONTRACT
 * ---------------------------------------------------------------------------
 * Respond_to_Webhook1 returns `{{ $json }}` — whatever the previous node
 * happened to hold. Before this node that was LOG_Audit's output, i.e. a
 * database row echo, and the response shape was an accident of which node ran
 * last. Now it is declared here, in one place, like the US workflow's
 * SHAPE_Response.
 *
 * Backward compatibility is deliberate: every field the dashboard already reads
 * from India (status, confidence, equipment_type, observations, violations,
 * site_id, asset_tag, inspector_id, image_url, audit_timestamp) keeps its name
 * and type. Everything else is additive, and the additions are fields the shared
 * report renderer ALREADY understands because the US workflow emits them — so
 * severity tiers, risk score and unverifiable items appear on an India report
 * with no frontend change at all.
 */

const dbResult = $input.first().json || {};
const a = $('PARSE_Response').first().json;

// n8n surfaces a continued error as `error` (and `$error` in some versions).
// Same test as the US workflow's BUILD_Report, so the two regions cannot drift
// on what "persisted" means.
const persisted = !(dbResult.error || dbResult.$error);

/**
 * The India table's primary key is a serial integer, and the insert echoes the
 * row, so a successful write can hand back the exact address of the record. That
 * is what the Records browser searches on (`record_id`) — India has no minted
 * audit_id, and this is its analogue. Absent when the write failed, which is
 * honest: there is no record to address.
 */
const record_id = persisted && (typeof dbResult.id === 'number' || typeof dbResult.id === 'string')
  ? dbResult.id
  : null;

return [{
  json: {
    // ---- fields the dashboard already consumes (names and types unchanged) ----
    status: a.status,
    confidence: a.confidence,
    equipment_type: a.equipment_type,
    observations: a.observations,
    violations: a.violations || [],
    site_id: a.site_id,
    asset_tag: a.asset_tag || null,
    inspector_id: a.inspector_id || null,
    image_url: a.image_url || null,
    audit_timestamp: a.audit_timestamp,

    // ---- identity / traceability ----
    audit_id: null,
    record_id: record_id,
    persisted: persisted,

    // ---- routing ----
    // IF_NonCompliant switches on this boolean instead of comparing status
    // strings. Keeping the branch condition in code means adding a status can
    // never silently create an unrouted path, which is exactly how REINSPECT
    // came to be handled in the notifier but unreachable from the IF node.
    alert_required: a.alert_required === true,

    // ---- severity model (roadmap 7.2) ----
    critical: a.critical === true,
    risk_score: a.risk_score,
    severity_counts: {
      critical: a.critical_count,
      major: a.major_count,
      minor: a.minor_count
    },
    deficiency_count: a.deficiency_count,
    deficiencies: a.deficiencies || [],
    unverifiable_items: a.unverifiable_items || [],
    image_quality: a.image_quality,
    reinspect_required: a.reinspect_required === true,
    reinspect_reasons: a.reinspect_reasons || [],
    // Surfaced rather than hidden: a code outside the checklist the model was
    // given means the prompt and the parser have drifted, and a reviewer should
    // be able to see that from the response.
    unknown_codes: a.unknown_codes || [],

    // ---- code basis actually applied ----
    // Hardcoded in the prompt for India rather than resolved from a registry, so
    // this is a static statement of what BUILD_Vision_Payload asserted, not a
    // lookup. Shaped like the US object so the renderer needs no India branch.
    code_basis: {
      jurisdiction_resolved: 'IN-MH',
      jurisdiction_label: 'Maharashtra, India',
      exact_match: true,
      // `fire_code` is the string the report renders as its whole code-basis
      // line, and the US registry entries are correspondingly full sentences
      // rather than bare code names. It is worded to match
      // REGIONS.IND.codeBasisFallback in lib/regions.ts EXACTLY, so a record that
      // carries a basis and one that falls back read identically — otherwise
      // shipping this would have made a live India audit display LESS statute
      // than before, since the fallback spells the whole regime out.
      fire_code: 'NBC 2016 Part 4, enforceable under the Maharashtra Fire Prevention and Life '
        + 'Safety Measures Act 2006 and Rules 2009 \u00b7 AHJ: Chief Fire Officer, MCGM',
      fire_code_edition: '2016, Part 4 (Fire and Life Safety)',
      life_safety_code: 'Maharashtra Fire Prevention and Life Safety Measures Act 2006; Rules 2009',
      ahj_label: 'Chief Fire Officer, Municipal Corporation (MCGM for Brihanmumbai)',
      state_overlays: ['IS 2190', 'IS 15683', 'BIS / ISI certification'],
      code_basis_confident: true
    },

    // ---- governance ----
    // The dashboard was supplying advisory_only: true for India on the frontend's
    // own authority. Now the workflow states it, so the claim travels with the
    // record instead of depending on which client rendered it. This is a
    // statement of scope, not sign-off: there are still no signoff columns on
    // field_audit_logs and no write path (roadmap 7.8/7.9, Form B).
    advisory_only: true,
    certification_eligible: false,
    requires_licensed_inspector_signoff: true,
    signoff_status: 'PENDING',
    scope_note: 'Photograph-based screening under NBC 2016 Part 4, read with the '
      + 'Maharashtra Fire Prevention and Life Safety Measures Act 2006 and Rules 2009. '
      + 'Not a Form B certification and not a substitute for inspection by a Licensed Agency.',

    region: 'IND'
  }
}];
